from scipy.optimize import brentq
g=9.8
a=df[(df.run>80)].copy()
def kfromv(v,h):
    f=lambda k: np.sqrt(g/k*(1-np.exp(-2*k*h)))-v
    try: return brentq(f,1e-7,10)
    except: return np.nan
def kfromt(t,h):
    f=lambda k: np.arccosh(np.exp(k*h))/np.sqrt(g*k)-t
    try: return brentq(f,1e-7,10)
    except: return np.nan
a['kv']=[kfromv(v,h) for v,h in zip(a.impact_speed,a.height)]
a['kt']=[kfromt(t,h) for t,h in zip(a.flight_time,a.height)]
for c in ['kv','kt']: a['Cd'+c[1]]=2*a.mass*a[c]/(a.air_density*np.pi*a.radius**2)
